use anyhow::Result;use solana_address::Address;use std::{env,str::FromStr};fn main()->Result<()>{for a in env::args().skip(1){let idl:serde_json::Value=serde_json::from_slice(&std::fs::read(&a)?)?;let p=Address::from_str(idl["address"].as_str().unwrap())?;for bump in 1u8..=4{let b=[bump];println!("{} bump{} {:?}",p,bump,Address::create_program_address(&[&[1],&[2],&[3],&[4],&b],&p));}}Ok(())}